index 0000000..0589d4d
--- /dev/null
+++ b/backend/tests/config.test.ts
@@ -0,0 +1,49 @@
+import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
+
+const keys = ['DATABASE_URL', 'POSTGRES_USER', 'POSTGRES_PASSWORD', 'POSTGRES_HOST', 'DB_PORT', 'POSTGRES_DB'];
+
+async function load() {
+  vi.resetModules();
+  return import('../src/core/config.ts');
+}
+
+describe('resolveDatabaseUrl', () => {
+  beforeEach(() => {
+    for (const key of keys) vi.stubEnv(key, '');
+  });
+  afterEach(() => {
+    vi.unstubAllEnvs();
+  });
+
+  it('prefers the override and rewrites the SQLAlchemy scheme of the environment URL', async () => {
+    vi.stubEnv('DATABASE_URL', 'postgresql+psycopg://u:p@h:5432/d');
+    const { resolveDatabaseUrl } = await load();
+    expect(resolveDatabaseUrl('postgresql://o@x/y')).toBe('postgresql://o@x/y');
+    expect(resolveDatabaseUrl()).toBe('postgresql://u:p@h:5432/d');
+  });
+
+  it('reports the first missing component variable by name', async () => {
+    vi.stubEnv('POSTGRES_USER', 'user');
+    vi.stubEnv('POSTGRES_PASSWORD', 'secret');
+    vi.stubEnv('DB_PORT', '5432');
+    vi.stubEnv('POSTGRES_DB', 'app');
+    const { resolveDatabaseUrl } = await load();
+    expect(() => resolveDatabaseUrl()).toThrow('Missing environment variable: POSTGRES_HOST');
+  });
+
+  it('builds the URL from components, percent-encoding credentials and database name', async () => {
+    vi.stubEnv('POSTGRES_USER', 'u@ser');
+    vi.stubEnv('POSTGRES_PASSWORD', 'p@ss:w/rd');
+    vi.stubEnv('POSTGRES_HOST', 'db.local');
+    vi.stubEnv('DB_PORT', '5432');
+    vi.stubEnv('POSTGRES_DB', 'my db%1');
+    const { resolveDatabaseUrl } = await load();
+    expect(resolveDatabaseUrl('')).toBe('postgresql://u%40ser:p%40ss%3Aw%2Frd@db.local:5432/my%20db%251');
+  });
+
+  it('falls back to the environment URL when the override is empty', async () => {
+    vi.stubEnv('DATABASE_URL', 'postgresql://e:f@envhost:5433/envdb');
+    const { resolveDatabaseUrl } = await load();
+    expect(resolveDatabaseUrl('')).toBe('postgresql://e:f@envhost:5433/envdb');
+  });
+});
