@@ -0,0 +1,23 @@
+import { expect, it, vi } from 'vitest';
+import { initialize } from '../src/core/database.ts';
+import type { Database } from '../src/features/todos/types.ts';
+
+it('issues a CREATE TABLE IF NOT EXISTS statement that keeps the compatible schema constraints and defaults', async () => {
+  const executeRaw = vi.fn().mockResolvedValue(0);
+  const database = { $executeRaw: executeRaw } as unknown as Database;
+
+  await initialize(database);
+
+  expect(executeRaw).toHaveBeenCalledOnce();
+  const [strings, ...values] = executeRaw.mock.calls[0] as [readonly string[], ...unknown[]];
+  expect(values).toEqual([]);
+  const sql = strings.join('');
+
+  expect(sql).toMatch(/CREATE\s+TABLE\s+IF\s+NOT\s+EXISTS\s+todos\s*\(/i);
+  expect(sql).toMatch(/title\s+VARCHAR\s*\(\s*120\s*\)\s+NOT\s+NULL/i);
+  expect(sql).toMatch(/CHECK\s*\(\s*length\s*\(\s*title\s*\)\s*>=\s*1\s*\)/i);
+  expect(sql).toMatch(/description\s+VARCHAR\s*\(\s*2000\s*\)\s+NOT\s+NULL\s+DEFAULT\s+''/i);
+  expect(sql).toMatch(/priority\s+VARCHAR\s*\(\s*6\s*\)\s+NOT\s+NULL\s+DEFAULT\s+'medium'/i);
+  expect(sql).toMatch(/CHECK\s*\(\s*priority\s+IN\s*\(\s*'low'\s*,\s*'medium'\s*,\s*'high'\s*\)\s*\)/i);
+  expect(sql).toMatch(/completed\s+BOOLEAN\s+NOT\s+NULL\s+DEFAULT\s+FALSE/i);
+});
diff --git a/backend/tests/factory.test.ts b/backend/tests/factory.test.ts
new file mode 100644
index 0000000..25fa72e
--- /dev/null
+++ b/backend/tests/factory.test.ts
@@ -0,0 +1,70 @@
+import { readFileSync } from 'node:fs';
+import request from 'supertest';
+import { afterEach, expect, it, vi } from 'vitest';
+import { createApp } from '../src/factory.ts';
+import type { Database } from '../src/features/todos/types.ts';
+
+afterEach(() => vi.restoreAllMocks());
+
+function setup() {
+  const failure = new Error('db secret');
+  const findFirst = vi.fn().mockRejectedValue(failure);
+  const findMany = vi.fn().mockResolvedValue([]);
+  const database = { todo: { findFirst, findMany } } as unknown as Database;
+  return { app: createApp(database), failure, findFirst, findMany };
+}
+
+it('serves repository data through the real router and hides the framework header', async () => {
+  const { app, findMany } = setup();
+  const response = await request(app).get('/api/todos');
+  expect(response.status).toBe(200);
+  expect(response.body).toEqual([]);
+  expect(findMany).toHaveBeenCalledOnce();
+  expect(response.headers['x-powered-by']).toBeUndefined();
+});
+
+it('returns a JSON 404 for unknown routes', async () => {
+  const { app } = setup();
+  const response = await request(app).get('/nope');
+  expect(response.status).toBe(404);
+  expect(response.body).toEqual({ detail: 'Not Found' });
+});
+
+it('maps malformed JSON to 422', async () => {
+  const { app } = setup();
+  const response = await request(app).post('/api/todos').set('Content-Type', 'application/json').send('{bad');
+  expect(response.status).toBe(422);
+  expect(response.body).toEqual({ detail: 'Invalid JSON.' });
+});
+
+it('maps oversized bodies to 413', async () => {
+  const { app } = setup();
+  const body = JSON.stringify({ title: 'a'.repeat(200 * 1024) });
+  const response = await request(app).post('/api/todos').set('Content-Type', 'application/json').send(body);
+  expect(response.status).toBe(413);
+  expect(response.body).toEqual({ detail: 'Request body too large.' });
+});
+
+it('hides internal error details from clients but logs them', async () => {
+  const { app, failure } = setup();
+  const log = vi.spyOn(console, 'error').mockImplementation(() => {});
+  const response = await request(app).get('/api/health');
+  expect(response.status).toBe(500);
+  expect(response.body).toEqual({ detail: 'Internal Server Error' });
+  expect(response.text).not.toContain('db secret');
+  expect(log).toHaveBeenCalledWith(failure);
+});
+
+it('serves the OpenAPI specification and the documentation UI', async () => {
+  const { app } = setup();
+  const expected = JSON.parse(readFileSync(new URL('../openapi.json', import.meta.url), 'utf8'));
+  const spec = await request(app).get('/openapi.json');
+  expect(spec.status).toBe(200);
+  expect(spec.headers['content-type']).toMatch(/application\/json/);
+  expect(spec.body).toEqual(expected);
+  expect(typeof spec.body.openapi).toBe('string');
+  expect(Object.keys(spec.body.paths).length).toBeGreaterThan(0);
+  const docs = await request(app).get('/docs/');
+  expect(docs.status).toBe(200);
+  expect(docs.headers['content-type']).toMatch(/text\/html/);
+});
