diff --git a/backend/tests/lifespan.test.ts b/backend/tests/lifespan.test.ts
new file mode 100644
index 0000000..8a99bfd
--- /dev/null
+++ b/backend/tests/lifespan.test.ts
@@ -0,0 +1,152 @@
+import { afterEach, beforeEach, expect, it, vi } from 'vitest';
+
+const mocks = vi.hoisted(() => ({
+  createDatabase: vi.fn(),
+  initialize: vi.fn(),
+  resolveDatabaseUrl: vi.fn(),
+  createApp: vi.fn(),
+}));
+
+vi.mock('../src/core/database.ts', () => ({
+  createDatabase: mocks.createDatabase,
+  initialize: mocks.initialize,
+}));
+vi.mock('../src/core/config.ts', () => ({ resolveDatabaseUrl: mocks.resolveDatabaseUrl }));
+vi.mock('../src/factory.ts', () => ({ createApp: mocks.createApp }));
+
+import { start } from '../src/core/lifespan.ts';
+
+beforeEach(() => {
+  vi.clearAllMocks();
+  mocks.resolveDatabaseUrl.mockReturnValue('postgresql://x');
+});
+afterEach(() => {
+  vi.restoreAllMocks();
+  vi.unstubAllEnvs();
+  vi.useRealTimers();
+});
+
+function fakeDatabase(connect: () => Promise<void>) {
+  const database = { $connect: vi.fn(connect), $disconnect: vi.fn().mockResolvedValue(undefined) };
+  mocks.createDatabase.mockReturnValue(database);
+  return database;
+}
+
+it('disconnects, rethrows the original error and builds no app when connecting fails', async () => {
+  const failure = new Error('down');
+  const database = fakeDatabase(() => Promise.reject(failure));
+  await expect(start()).rejects.toBe(failure);
+  expect(mocks.createDatabase).toHaveBeenCalledWith('postgresql://x');
+  expect(database.$disconnect).toHaveBeenCalledOnce();
+  expect(mocks.initialize).not.toHaveBeenCalled();
+  expect(mocks.createApp).not.toHaveBeenCalled();
+});
+
+it('disconnects, rethrows the original error and builds no app when initialization fails', async () => {
+  const failure = new Error('ddl failed');
+  const database = fakeDatabase(() => Promise.resolve());
+  mocks.initialize.mockRejectedValue(failure);
+  await expect(start()).rejects.toBe(failure);
+  expect(database.$connect).toHaveBeenCalledOnce();
+  expect(mocks.initialize).toHaveBeenCalledWith(database);
+  expect(database.$disconnect).toHaveBeenCalledOnce();
+  expect(mocks.createApp).not.toHaveBeenCalled();
+});
+
+it.each([
+  ['9123', 9123],
+  [undefined, 8000],
+])('listens on API_PORT=%s (port %i) at 0.0.0.0 and returns the server and database', async (apiPort, expectedPort) => {
+  vi.stubEnv('API_PORT', apiPort);
+  vi.spyOn(process, 'once').mockImplementation(() => process);
+  const log = vi.spyOn(console, 'log').mockImplementation(() => {});
+  const database = fakeDatabase(() => Promise.resolve());
+  mocks.initialize.mockResolvedValue(undefined);
+  const listener = {
+    once: vi.fn(),
+    address: vi.fn().mockReturnValue({ port: expectedPort }),
+    close: vi.fn(),
+  };
+  const listen = vi.fn((_port: number, _host: string, callback: () => void) => {
+    queueMicrotask(callback);
+    return listener;
+  });
+  mocks.createApp.mockReturnValue({ listen });
+
+  const result = await start();
+
+  expect(database.$connect).toHaveBeenCalledOnce();
+  expect(mocks.initialize).toHaveBeenCalledWith(database);
+  expect(mocks.createApp).toHaveBeenCalledWith(database);
+  expect(listen).toHaveBeenCalledOnce();
+  expect(listen).toHaveBeenCalledWith(expectedPort, '0.0.0.0', expect.any(Function));
+  expect(result.server).toBe(listener);
+  expect(result.database).toBe(database);
+  expect(database.$disconnect).not.toHaveBeenCalled();
+  expect(log).toHaveBeenCalledWith(expect.stringContaining(String(expectedPort)));
+});
+
+it('rejects with the listener error and disconnects the database', async () => {
+  vi.stubEnv('API_PORT', '9123');
+  const processOnce = vi.spyOn(process, 'once').mockImplementation(() => process);
+  const database = fakeDatabase(() => Promise.resolve());
+  mocks.initialize.mockResolvedValue(undefined);
+  const failure = Object.assign(new Error('address in use'), { code: 'EADDRINUSE' });
+  const listener = {
+    once: vi.fn((event: string, handler: (error: Error) => void) => {
+      if (event === 'error') queueMicrotask(() => handler(failure));
+    }),
+    address: vi.fn(),
+    close: vi.fn(),
+  };
+  const listen = vi.fn(() => listener);
+  mocks.createApp.mockReturnValue({ listen });
+
+  await expect(start()).rejects.toBe(failure);
+
+  expect(listen).toHaveBeenCalledOnce();
+  expect(database.$disconnect).toHaveBeenCalledOnce();
+  expect(processOnce).not.toHaveBeenCalled();
+});
+
+it('closes the server on SIGTERM, disconnects only after the close completes and does not exit', async () => {
+  vi.stubEnv('API_PORT', '9123');
+  const processOnce = vi.spyOn(process, 'once').mockImplementation(() => process);
+  const exit = vi.spyOn(process, 'exit').mockImplementation((() => undefined) as never);
+  vi.spyOn(console, 'log').mockImplementation(() => {});
+  const database = fakeDatabase(() => Promise.resolve());
+  mocks.initialize.mockResolvedValue(undefined);
+  let closeCallback!: () => Promise<void>;
+  const listener = {
+    once: vi.fn(),
+    address: vi.fn().mockReturnValue({ port: 9123 }),
+    close: vi.fn((callback: () => Promise<void>) => {
+      closeCallback = callback;
+    }),
+  };
+  const listen = vi.fn((_port: number, _host: string, callback: () => void) => {
+    queueMicrotask(callback);
+    return listener;
+  });
+  mocks.createApp.mockReturnValue({ listen });
+
+  await start();
+
+  expect(processOnce).toHaveBeenCalledWith('SIGTERM', expect.any(Function));
+  expect(processOnce).toHaveBeenCalledWith('SIGINT', expect.any(Function));
+  const sigterm = processOnce.mock.calls.find(([event]) => event === 'SIGTERM')![1] as () => void;
+
+  vi.useFakeTimers();
+  sigterm();
+
+  expect(listener.close).toHaveBeenCalledOnce();
+  expect(database.$disconnect).not.toHaveBeenCalled();
+
+  await closeCallback();
+
+  expect(database.$disconnect).toHaveBeenCalledOnce();
+  expect(exit).not.toHaveBeenCalled();
+  // The forced-exit timer must have been cleared once shutdown finished cleanly.
+  vi.advanceTimersByTime(10000);
+  expect(exit).not.toHaveBeenCalled();
+});
