+  ['get', '/api/todos/0'],
+  ['patch', '/api/todos/-1'],
+  ['delete', '/api/todos/1.5'],
+] as const)('rejects invalid id with %s %s before calling the repository', async (method, url) => {
+  const { app, repository } = setup();
+  const response = await request(app)[method](url).send(method === 'patch' ? { completed: true } : undefined);
+  expect(response.status).toBe(422);
+  expect(Array.isArray(response.body.detail)).toBe(true);
+  expect(response.body.detail.length).toBeGreaterThan(0);
+  expect(repository.get).not.toHaveBeenCalled();
+  expect(repository.update).not.toHaveBeenCalled();
+  expect(repository.delete).not.toHaveBeenCalled();
+});
+it('gets a task by numeric id and maps a missing task to 404', async () => {
+  const { app, repository } = setup();
+  repository.get.mockResolvedValueOnce(todo).mockResolvedValueOnce(null);
+  const found = await request(app).get('/api/todos/12');
+  expect(found.status).toBe(200);
+  expect(found.body).toEqual(todo);
+  expect(repository.get).toHaveBeenNthCalledWith(1, 12);
+  const missing = await request(app).get('/api/todos/12');
+  expect(missing.status).toBe(404);
+  expect(missing.body).toEqual({ detail: 'Task not found.' });
+});
+it('patches a task with parsed input and maps a missing task to 404', async () => {
+  const { app, repository } = setup();
+  repository.update.mockResolvedValueOnce(todo).mockResolvedValueOnce(null);
+  const found = await request(app).patch('/api/todos/12').send({ title: '  New  ' });
+  expect(found.status).toBe(200);
+  expect(found.body).toEqual(todo);
+  expect(repository.update).toHaveBeenNthCalledWith(1, 12, { title: 'New' });
+  const missing = await request(app).patch('/api/todos/12').send({ completed: true });
+  expect(missing.status).toBe(404);
+  expect(missing.body).toEqual({ detail: 'Task not found.' });
+  expect(repository.update).toHaveBeenNthCalledWith(2, 12, { completed: true });
+});
+it('rejects an empty patch without calling the repository', async () => {
+  const { app, repository } = setup();
+  const response = await request(app).patch('/api/todos/12').send({});
+  expect(response.status).toBe(422);
+  expect(response.body.detail.length).toBeGreaterThan(0);
+  expect(repository.update).not.toHaveBeenCalled();
+});
+it('deletes with an empty 204 and maps a missing task to 404', async () => {
+  const { app, repository } = setup();
+  repository.delete.mockResolvedValueOnce(true).mockResolvedValueOnce(false);
+  const removed = await request(app).delete('/api/todos/12');
+  expect(removed.status).toBe(204);
+  expect(removed.text).toBe('');
+  expect(repository.delete).toHaveBeenNthCalledWith(1, 12);
+  const missing = await request(app).delete('/api/todos/12');
+  expect(missing.status).toBe(404);
+  expect(missing.body).toEqual({ detail: 'Task not found.' });
+});
