+import { QueryClient, useQueryClient } from '@tanstack/react-query'
+import { render, screen } from '@testing-library/react'
+import { beforeEach, expect, it, vi } from 'vitest'
+import { GlobalStyles } from '../design-system'
+import { queryClient } from '../lib/queryClient'
+import { AppProviders } from './AppProviders'
+
+vi.mock('../design-system', () => import('../design-system/mocks'))
+beforeEach(() => vi.clearAllMocks())
+
+function setupProbe() {
+  const seen: QueryClient[] = []
+  function Probe() {
+    seen.push(useQueryClient())
+    return <p>Child content</p>
+  }
+  return { seen, Probe }
+}
+
+it('provides the given query client, renders children and mounts global styles', () => {
+  const custom = new QueryClient()
+  const { seen, Probe } = setupProbe()
+  render(
+    <AppProviders client={custom}>
+      <Probe />
+    </AppProviders>,
+  )
+  expect(screen.getByText('Child content')).toBeVisible()
+  expect(seen[0]).toBe(custom)
+  expect(seen[0]).not.toBe(queryClient)
+  expect(GlobalStyles).toHaveBeenCalled()
+})
+
+it('falls back to the shared query client', () => {
+  const { seen, Probe } = setupProbe()
+  render(
+    <AppProviders>
+      <Probe />
+    </AppProviders>,
+  )
+  expect(screen.getByText('Child content')).toBeVisible()
+  expect(seen[0]).toBe(queryClient)
+})
