+import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
+import { act, renderHook } from '@testing-library/react'
+import type { ReactNode } from 'react'
+import { beforeEach, expect, it, vi } from 'vitest'
+import { todoFixture } from '../../../test/todoFixture'
+import { todoKeys } from '../api/queryKeys'
+import { todosApi } from '../api/todos'
+import type { Todo, TodoInput } from '../types'
+import { useCreateTodoMutation } from './useCreateTodoMutation'
+
+vi.mock('../api/todos', () => ({ todosApi: { create: vi.fn() } }))
+beforeEach(() => vi.clearAllMocks())
+
+const other: Todo = { ...todoFixture, id: 1, title: 'Other task' }
+const saved: Todo = { ...todoFixture, id: 7, title: 'Saved title' }
+const input: TodoInput = {
+  title: saved.title,
+  description: '',
+  priority: 'medium',
+  due_date: null,
+  completed: false,
+}
+
+function setup() {
+  const client = new QueryClient({
+    defaultOptions: { queries: { retry: false, gcTime: Infinity } },
+  })
+  const wrapper = ({ children }: { children: ReactNode }) => (
+    <QueryClientProvider client={client}>{children}</QueryClientProvider>
+  )
+  const { result } = renderHook(() => useCreateTodoMutation(), { wrapper })
+  return { client, result }
+}
+
+it('prepends the saved task and removes a stale duplicate', async () => {
+  const { client, result } = setup()
+  client.setQueryData<Todo[]>(todoKeys.list, [
+    other,
+    { ...todoFixture, id: 7, title: 'Stale title' },
+  ])
+  vi.mocked(todosApi.create).mockResolvedValue(saved)
+  await act(async () => {
+    await result.current.mutateAsync(input)
+  })
+  expect(todosApi.create).toHaveBeenCalledWith(input)
+  expect(client.getQueryData(todoKeys.list)).toEqual([saved, other])
+})
+
+it('starts a list from the saved task when nothing is cached', async () => {
+  const { client, result } = setup()
+  vi.mocked(todosApi.create).mockResolvedValue(saved)
+  await act(async () => {
+    await result.current.mutateAsync(input)
+  })
+  expect(client.getQueryData(todoKeys.list)).toEqual([saved])
+})
+
+it('cancels an in-flight list fetch so its late result cannot overwrite the saved task', async () => {
+  const { client, result } = setup()
+  client.setQueryData<Todo[]>(todoKeys.list, [other])
+  let release!: (value: Todo[]) => void
+  let signal!: AbortSignal
+  const inFlight = client
+    .fetchQuery({
+      queryKey: todoKeys.list,
+      staleTime: 0,
+      queryFn: ({ signal: querySignal }) => {
+        signal = querySignal
+        return new Promise<Todo[]>((resolve) => {
+          release = resolve
+        })
+      },
+    })
+    .catch(() => undefined)
+  expect(signal.aborted).toBe(false)
+  vi.mocked(todosApi.create).mockResolvedValue(saved)
+  await act(async () => {
+    await result.current.mutateAsync(input)
+  })
+  expect(signal.aborted).toBe(true)
+  release([other, { ...todoFixture, id: 99, title: 'Late result' }])
+  await inFlight
+  expect(client.getQueryData(todoKeys.list)).toEqual([saved, other])
+})
