+    await result.current.mutateAsync(7)
+  })
+  expect(todosApi.remove).toHaveBeenCalledWith(7)
+  expect(client.getQueryData(todoKeys.list)).toBeUndefined()
+})
+
+it('cancels an in-flight list fetch so its late result cannot resurrect the task', async () => {
+  const { client, result } = setup()
+  client.setQueryData<Todo[]>(todoKeys.list, [a, b])
+  let release!: (value: Todo[]) => void
+  let signal!: AbortSignal
+  const inFlight = client
+    .fetchQuery({
+      queryKey: todoKeys.list,
+      staleTime: 0,
+      queryFn: ({ signal: querySignal }) => {
+        signal = querySignal
+        return new Promise<Todo[]>((resolve) => {
+          release = resolve
+        })
+      },
+    })
+    .catch(() => undefined)
+  expect(signal.aborted).toBe(false)
+  vi.mocked(todosApi.remove).mockResolvedValue(undefined)
+  await act(async () => {
+    await result.current.mutateAsync(7)
+  })
+  expect(signal.aborted).toBe(true)
+  release([a, b])
+  await inFlight
+  expect(client.getQueryData(todoKeys.list)).toEqual([a])
