+import { act, renderHook } from '@testing-library/react'
+import { expect, it } from 'vitest'
+import { todoFixture } from '../../../test/todoFixture'
+import type { Todo } from '../types'
+import { useTodoFilters } from './useTodoFilters'
+
+const alpha: Todo = {
+  ...todoFixture,
+  id: 1,
+  title: 'Alpha',
+  completed: true,
+  priority: 'high',
+}
+const beta: Todo = {
+  ...todoFixture,
+  id: 2,
+  title: 'Beta',
+  completed: false,
+  priority: 'low',
+}
+const todos = [alpha, beta]
+
+it('starts with all/empty/newest and shows every task', () => {
+  const { result } = renderHook(() => useTodoFilters(todos))
+  expect(result.current.filter).toBe('all')
+  expect(result.current.search).toBe('')
+  expect(result.current.sort).toBe('newest')
+  expect(result.current.visible.map((t) => t.id)).toEqual([2, 1])
+})
+
+it('recomputes visible tasks when filter, search and sort change', () => {
+  const { result } = renderHook(() => useTodoFilters(todos))
+  act(() => result.current.setFilter('completed'))
+  expect(result.current.filter).toBe('completed')
+  expect(result.current.visible).toEqual([alpha])
+
+  act(() => result.current.setFilter('all'))
+  act(() => result.current.setSearch('bet'))
+  expect(result.current.search).toBe('bet')
+  expect(result.current.visible).toEqual([beta])
+
+  act(() => result.current.setSearch(''))
+  act(() => result.current.setSort('priority'))
+  expect(result.current.sort).toBe('priority')
+  expect(result.current.visible.map((t) => t.id)).toEqual([1, 2])
+})
