+    ]
+    expect(selectTodos(todos, 'all', '', 'due').map((t) => t.id)).toEqual([
+      4, 2, 1, 3,
+    ])
+  })
+
+  it('sorts newest by creation time, then by higher id', () => {
+    const todos: Todo[] = [
+      { ...base, id: 1, created_at: '2026-10-01T12:00:00Z' },
+      { ...base, id: 2, created_at: '2026-10-03T12:00:00Z' },
+      { ...base, id: 3, created_at: '2026-10-03T12:00:00Z' },
+      { ...base, id: 4, created_at: '2026-09-01T12:00:00Z' },
+    ]
+    expect(selectTodos(todos, 'all', '', 'newest').map((t) => t.id)).toEqual([
+      3, 2, 1, 4,
+    ])
+  })
+
+  it('keeps only completed tasks for the completed filter', () => {
+    const todos: Todo[] = [
+      { ...base, id: 1, completed: true },
+      { ...base, id: 2, completed: false },
+      { ...base, id: 3, completed: true },
+    ]
+    expect(
+      selectTodos(todos, 'completed', '', 'newest').map((t) => t.id),
+    ).toEqual([3, 1])
+  })
+})
+
+describe('isOverdue', () => {
+  afterEach(() => vi.useRealTimers())
+
+  it('is true only for active tasks due before the local calendar day', () => {
+    vi.useFakeTimers()
+    vi.setSystemTime(new Date(2026, 9, 16, 12, 0, 0))
+    expect(isOverdue({ ...base, due_date: '2026-10-15' })).toBe(true)
+    expect(isOverdue({ ...base, due_date: '2026-10-16' })).toBe(false)
+    expect(isOverdue({ ...base, due_date: '2026-10-17' })).toBe(false)
+    expect(isOverdue({ ...base, due_date: null })).toBe(false)
+    expect(
+      isOverdue({ ...base, due_date: '2026-10-15', completed: true }),
+    ).toBe(false)
+  })
+})
+
+describe('formatDate', () => {
+  it.each([
+    ['2026-10-05', '5 Oct 2026'],
+    ['2026-01-01', '1 Jan 2026'],
+  ])('formats %s as %s', (date, expected) => {
+    expect(formatDate(date)).toBe(expected)
+  })
+})
+
+describe('validateTodo', () => {
+  const valid: TodoInput = {
+    title: 'Task',
+    description: '',
+    priority: 'medium',
+    due_date: null,
+    completed: false,
+  }
+
+  it.each<[string, Partial<TodoInput>, Record<string, string>]>([
+    ['title of 120 trimmed characters', { title: `  ${'x'.repeat(120)}  ` }, {}],
+    [
+      'title of 121 characters',
+      { title: 'x'.repeat(121) },
+      { title: 'The title must be at most 120 characters.' },
+    ],
+    ['blank title', { title: '   ' }, { title: 'Enter a task title.' }],
+    ['description of 2000 trimmed characters', { description: ` ${'x'.repeat(2000)} ` }, {}],
+    [
+      'description of 2001 characters',
+      { description: 'x'.repeat(2001) },
+      { description: 'The description must be at most 2000 characters.' },
+    ],
+    ['rolled-over date', { due_date: '2026-02-30' }, { due_date: 'Enter a valid date.' }],
+    ['non-leap Feb 29', { due_date: '2025-02-29' }, { due_date: 'Enter a valid date.' }],
+    ['unpadded date', { due_date: '2026-1-5' }, { due_date: 'Enter a valid date.' }],
+    ['leap day', { due_date: '2024-02-29' }, {}],
+    ['null date', { due_date: null }, {}],
+    ['empty date', { due_date: '' }, {}],
+  ])('%s', (_name, override, expected) => {
+    expect(validateTodo({ ...valid, ...override })).toEqual(expected)
+  })
 })
