--- /dev/null
+++ b/frontend/src/lib/http.test.ts
@@ -0,0 +1,91 @@
+import { afterEach, expect, it, vi } from 'vitest'
+import { request } from './http'
+
+afterEach(() => vi.unstubAllGlobals())
+
+function stubFetch(impl: (...args: unknown[]) => unknown) {
+  const fetchMock = vi.fn(impl)
+  vi.stubGlobal('fetch', fetchMock)
+  return fetchMock
+}
+
+it('reports a connection error when fetch fails without an abort', async () => {
+  stubFetch(() => Promise.reject(new TypeError('Failed to fetch')))
+  await expect(request('/x')).rejects.toThrow(
+    'Cannot connect to the server. Please try again.',
+  )
+})
+
+it('rethrows the original error when the caller aborted the request', async () => {
+  const controller = new AbortController()
+  controller.abort()
+  const abortError = new DOMException('The operation was aborted.', 'AbortError')
+  const fetchMock = stubFetch(() => Promise.reject(abortError))
+  await expect(request('/x', { signal: controller.signal })).rejects.toBe(
+    abortError,
+  )
+  expect(fetchMock.mock.calls[0][1]).toEqual(
+    expect.objectContaining({ signal: controller.signal }),
+  )
+})
+
+it('maps a 422 response to the task details message', async () => {
+  stubFetch(() =>
+    Promise.resolve({
+      ok: false,
+      status: 422,
+      json: () => Promise.resolve({ detail: [{ msg: 'raw backend issue' }] }),
+    }),
+  )
+  await expect(request('/x')).rejects.toThrow(
+    'Check the task details: title up to 120 characters, description up to 2000 characters, and a valid due date.',
+  )
+})
+
+it('surfaces a string server detail', async () => {
+  stubFetch(() =>
+    Promise.resolve({
+      ok: false,
+      status: 500,
+      json: () => Promise.resolve({ detail: 'Boom' }),
+    }),
+  )
+  await expect(request('/x')).rejects.toThrow('Boom')
+})
+
+it.each([
+  ['a non-JSON body', () => Promise.reject(new SyntaxError('bad json'))],
+  ['a non-string detail', () => Promise.resolve({ detail: { a: 1 } })],
+])('uses the generic failure message for %s', async (_name, json) => {
+  stubFetch(() => Promise.resolve({ ok: false, status: 500, json }))
+  await expect(request('/x')).rejects.toThrow(
+    'The operation failed. Please try again.',
+  )
+})
+
+it('resolves undefined for 204 without reading a body', async () => {
+  const json = vi.fn()
+  stubFetch(() => Promise.resolve({ ok: true, status: 204, json }))
+  await expect(request('/x', { method: 'DELETE' })).resolves.toBeUndefined()
+  expect(json).not.toHaveBeenCalled()
+})
+
+it('prefixes the path, merges headers and returns the parsed body', async () => {
+  const fetchMock = stubFetch(() =>
+    Promise.resolve({
+      ok: true,
+      status: 200,
+      json: () => Promise.resolve({ id: 5 }),
+    }),
+  )
+  await expect(
+    request('/todos', { method: 'POST', headers: { 'X-Test': '1' } }),
+  ).resolves.toEqual({ id: 5 })
+  expect(fetchMock).toHaveBeenCalledWith(
+    '/api/todos',
+    expect.objectContaining({
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json', 'X-Test': '1' },
+    }),
+  )
+})
